export const pokerLevels=[{min:0,key:'rookie'},{min:250,key:'apprentice'},{min:1000,key:'reader'},{min:2500,key:'strategist'},{min:5000,key:'grinder'},{min:10000,key:'shark'},{min:20000,key:'master'},{min:40000,key:'champion'}];
export function activityDifficulty(question,theme){if(theme==='math'||question.kind==='showdown'||theme==='decisions'&&question.game)return {key:'advanced',xp:40};if(question.type==='sequence')return {key:'intermediate',xp:30};if(question.type==='binary')return {key:'basic',xp:10};return {key:'standard',xp:20}}
export function xpSummary(rows){const total=rows.reduce((sum,row)=>sum+(row.correct&&Number.isFinite(row.xp)&&row.xp>0?row.xp:0),0);const level=[...pokerLevels].reverse().find(level=>total>=level.min);const next=pokerLevels[pokerLevels.indexOf(level)+1];const progress=next?Math.min(100,Math.round((total-level.min)/(next.min-level.min)*100)):100;return {total,level,next,progress}}
export function dailyRanking(rows){const days=new Map();for(const row of rows){if(!row.correct||!Number.isFinite(row.xp)||row.xp<=0)continue;const date=new Date(row.at);const day=[date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');days.set(day,(days.get(day)||0)+row.xp)}return [...days].map(([day,xp])=>({day,xp})).sort((a,b)=>b.xp-a.xp||b.day.localeCompare(a.day))}
